import{_ as a,o as i,c as e,ae as s}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"How the Tech Radar works","description":"","frontmatter":{"title":"How the Tech Radar works"},"headers":[],"relativePath":"radar/how-it-works.md","filePath":"radar/how-it-works.md"}'),n={name:"radar/how-it-works.md"};function r(d,t,o,h,l,p){return i(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="how-the-tech-radar-works" tabindex="-1">How the Tech Radar works <a class="header-anchor" href="#how-the-tech-radar-works" aria-label="Permalink to &quot;How the Tech Radar works&quot;">​</a></h1><h2 id="rings" tabindex="-1">Rings <a class="header-anchor" href="#rings" aria-label="Permalink to &quot;Rings&quot;">​</a></h2><p>A ring is a statement about commitment, not about quality.</p><table tabindex="0"><thead><tr><th>Ring</th><th>Meaning</th></tr></thead><tbody><tr><td>Adopt</td><td>The default choice. Picking something else needs a justification.</td></tr><tr><td>Trial</td><td>Worth pursuing on real work, with someone accountable for the outcome.</td></tr><tr><td>Assess</td><td>Worth understanding and prototyping, not yet worth committing to.</td></tr><tr><td>Hold</td><td>Do not start anything new with it. Existing usage is not an emergency.</td></tr></tbody></table><h2 id="quadrants" tabindex="-1">Quadrants <a class="header-anchor" href="#quadrants" aria-label="Permalink to &quot;Quadrants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quadrant</th><th>Holds</th></tr></thead><tbody><tr><td>Techniques</td><td>Ways of working, practices, and design approaches.</td></tr><tr><td>Tools</td><td>Software we run to build, verify, or operate things.</td></tr><tr><td>Platforms</td><td>Things we build on top of, such as runtimes, infrastructure, hosted services.</td></tr><tr><td>Languages &amp; Frameworks</td><td>Programming languages and the libraries we write code against.</td></tr></tbody></table><p>Every quadrant also has its own page, holding one quadrant of the board and the full list for it. That is the place to read a crowded quadrant, and it is reachable from the quadrant name on the board.</p><p>Rings, quadrants, and editions are data, not code. They live in <code>.vitepress/radar.ts</code>, and every blip is validated against them at build time. Adding a quadrant there adds its page and its sidebar entry.</p><h2 id="editions" tabindex="-1">Editions <a class="header-anchor" href="#editions" aria-label="Permalink to &quot;Editions&quot;">​</a></h2><p>The radar is published as editions. A blip does not carry a current ring; it carries the ring it held in each edition it appeared in:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">history</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">edition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2026.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">assess</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">edition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2026.2&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">trial</span></span></code></pre></div><p>The ring shown on the board is the one from the newest published edition that the blip has an entry for. Movement is a statement about the current edition only: a blip with no entry for it did not move, whatever it did in the past. This is why the board can show that something moved without anyone maintaining a &quot;moved&quot; flag by hand:</p><ul><li>A circle means the ring did not change.</li><li>A triangle pointing inward means it moved toward Adopt.</li><li>A triangle pointing outward means it moved away from Adopt.</li><li>A dashed halo means the blip is new in this edition.</li></ul><p>A blip whose history starts in a future edition is not rendered, so the next edition can be prepared in the open without publishing it early.</p><h2 id="adding-or-moving-a-blip" tabindex="-1">Adding or moving a blip <a class="header-anchor" href="#adding-or-moving-a-blip" aria-label="Permalink to &quot;Adding or moving a blip&quot;">​</a></h2><p>Create the file:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_radar_item</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Some Technology&quot;</span></span></code></pre></div><p>Then fill in the frontmatter and say why in the body. Rules the build enforces:</p><ul><li><code>quadrant</code> and every <code>ring</code> must exist in the taxonomy.</li><li>Every <code>edition</code> must exist in the edition list, and may appear at most once per blip.</li><li><code>adr</code>, when present, must point at a real ADR directory under <code>src/adrs</code>.</li></ul><p>Moving a blip means appending a new entry to its history for the current edition. Never edit a past entry, because that rewrites what the radar said at the time.</p><p>A blip that overlaps an existing decision should link to it with <code>adr</code>. If the ring you want contradicts an approved ADR, the ADR is the thing to change first.</p>`,21)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
